"""Build dependency-free public pages from reviewed static copy."""
from pathlib import Path
ROOT=Path(__file__).parent / 'dist'
NAV=[('Features','features.html'),('Downloads','downloads.html'),('Documentation','docs.html'),('Research','research.html')]
def page(title,content):
    nav=''.join(f'<a href="/{url}"'+(' aria-current="page"' if title==name else '')+f'>{name}</a>' for name,url in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Sentinel AI: independent local authorization for supported AI-agent tools. Optional private cloud telemetry."><title>{title} · Sentinel AI</title><link rel="icon" href="/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script defer src="/public.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><img src="/mark.svg" width="30" height="34" alt="">SENTINEL <span>AI</span></a><nav aria-label="Main navigation">{nav}<a class="nav-dash" href="/dashboard.html">Cloud dashboard <span aria-hidden="true">↗</span></a></nav></header><main id="main">{content}</main><footer><a class="brand" href="/">SENTINEL <span>AI</span></a><p>Local decisions. Independent enforcement.</p><div><a href="/docs.html#limitations">Security boundaries</a><a href="/docs.html#privacy">Privacy</a><a href="/docs.html#disclosure">Report a vulnerability</a></div><small>Research software · Public-release candidate · Not independently certified</small></footer></body></html>'''
home='''<section class="hero"><div><p class="eyebrow">LOCAL-FIRST AGENT SECURITY</p><h1>Your agent can propose.<br><em>Only policy can permit.</em></h1><p class="lede">Put an independent security gateway between an AI agent and its tools. Keep task authority on your machine, even when the instructions it reads cannot be trusted.</p><div class="actions"><a class="button" href="/downloads.html">Get Sentinel AI <span>↗</span></a><a class="button secondary" href="/docs.html">Read the documentation</a></div><p class="caption">Rust enforcement · Python integration · Optional cloud visibility</p></div><div class="flow-panel" aria-label="Architecture illustration, not live activity"><div class="panel-label">THE AUTHORIZATION BOUNDARY <span>01 / LOCAL</span></div><div class="flow-node"><span class="number">01</span><div><strong>AI agent</strong><small>Untrusted proposal</small></div><code>read_file</code></div><div class="flow-line">↓</div><div class="flow-node gateway"><span class="number">02</span><div><strong>Sentinel gateway</strong><small>Identity · Scope · Expiry · Policy</small></div><span class="tag">TRUSTED</span></div><div class="decision-row"><span>ALLOW</span><span>DENY</span><span>APPROVAL</span></div><div class="flow-line">↓</div><div class="flow-node"><span class="number">03</span><div><strong>Restricted tool</strong><small>Execute only after authorization</small></div></div><p class="caption">Illustrative request flow. Every supported action receives its own decision and audit record.</p></div></section><section class="statement"><p class="eyebrow">AUTHORIZATION IS NOT A MODEL OUTPUT</p><h2>Useful autonomy needs<br>a separate source of authority.</h2><p>A malicious document can influence a model. It cannot sign a task contract, grant an approval or expand the gateway’s permissions. Sentinel enforces those decisions in trusted code outside the model.</p></section><section><div class="section-head"><h2>Small permissions.<br>Clear boundaries.</h2><a href="/features.html">Explore the controls ↗</a></div><div class="three"><article><span class="index">01 / AUTHORIZE</span><h3>Bound every task</h3><p>Signed contracts describe which operations and exact resources a task may use, and when that authority expires.</p></article><article><span class="index">02 / ENFORCE</span><h3>Check every request</h3><p>Default-deny policy, one-time approvals and restricted execution keep decisions separate from model-generated instructions.</p></article><article><span class="index">03 / OBSERVE</span><h3>Understand the outcome</h3><p>Inspect local audit records. Optionally synchronize an allowlist of event metadata to a private account.</p></article></div></section><section class="split-band"><div><p class="eyebrow">YOUR MACHINE IS THE CONTROL PLANE</p><h2>Cloud visibility.<br>Local authority.</h2></div><div><p>The online dashboard observes device-reported events. It cannot run commands, read files, approve actions or edit trusted policies on your computer.</p><p>Synchronization is off by default. Prompts, documents, tool responses, resource names and signing keys stay local.</p><a href="/docs.html#privacy">Read the privacy architecture ↗</a></div></section><section><div class="section-head"><h2>Start with a controlled task.</h2><a href="/docs.html#start">Getting started ↗</a></div><ol class="steps"><li><b>Install a verified package</b><p>Choose a supported platform and verify its checksum before installation.</p></li><li><b>Connect supported tools</b><p>Use the Python SDK to route every protected operation through the Rust gateway.</p></li><li><b>Inspect real decisions</b><p>Run synthetic allowed and denied requests; inspect their local audit records.</p></li></ol><div class="notice">Sentinel does not automatically protect arbitrary applications. Tools that bypass its gateway are outside its security boundary. <a href="/docs.html#limitations">Understand the limitations.</a></div></section>'''
features='''<section class="page-intro"><p class="eyebrow">SECURITY CONTROLS</p><h1>Enforcement beyond<br>the prompt.</h1><p class="lede">A composable local runtime for supported agent tools. Each control has an explicit scope and a testable outcome.</p></section><section class="feature-list">'''+''.join(f'<article><span class="index">{i:02}</span><div><h2>{a}</h2><p>{b}</p></div></article>' for i,(a,b) in enumerate([
('Default-deny authorization','A request is denied unless its authenticated task contract and policy authorize the operation and resource. Model confidence never substitutes for authority.'),('Signed, expiring task contracts','Trusted controllers issue task-scoped authority. Agent-generated instructions cannot modify signatures, permissions or expiration.'),('Human approvals and replay protection','Sensitive authorized operations can require a local authenticated approval. Approvals bind to the exact request and can be consumed only once. The cloud cannot issue them.'),('Revocation and audit correlation','Local task revocation stops the runtime. SQLite records decisions and execution metadata so proposals, authorization and actual execution can be distinguished.'),('Restricted execution','Simulated APIs have no production connectivity. Unix descriptor-pinned file tools and a fixed, bounded Wasm tool provide deliberately narrow execution capabilities.'),('Prompt-injection impact containment','Malicious tool content remains untrusted. Gateway restrictions still apply when a model follows hostile instructions. This is not a claim of detection or complete immunity.'),('Experimental provenance controls','Protected observations can mark a task and block subsequent sinks. This conservative research mechanism is not complete information-flow tracking.'),('Optional private telemetry','Only explicitly allowed event metadata may leave the device. Cloud outages do not change local authorization; cloud events are endpoint reports, not tamper-proof evidence.')],1))+'''</section><section class="notice">Native Windows filesystem isolation remains disabled. WSL2 is the documented Windows alternative; native Windows compatibility is not advertised as verified.</section>'''
downloads='''<section class="page-intro"><p class="eyebrow">INSTALL SENTINEL AI</p><h1>Bring the gateway<br>to your machine.</h1><p class="lede">Candidate 0.3.0-rc.1 artifacts are prepared for owner-controlled publication. No public GitHub repository or published release has been configured in this website.</p></section><section><div id="release-status" class="notice">Downloads are unavailable until the maintainer publishes and configures an official release. Do not trust packages from an unverified source.</div><div class="three platform-grid"><article><span class="index">macOS</span><h2>Apple Silicon</h2><p>Bundled runtime and offline installer tested on Apple Silicon. Python 3.12+ is required; no Rust compiler is needed for the package.</p><button disabled>Release not published</button><small>Unsigned / not notarized unless a release explicitly states otherwise.</small></article><article><span class="index">LINUX</span><h2>Linux</h2><p>ARM64 package and installer tested in Debian 12 (glibc 2.36). Linux x86_64 builds remain a CI verification step.</p><button disabled>Release not published</button><small>See the release-specific build and test matrix.</small></article><article><span class="index">WINDOWS 10 / 11</span><h2>Use WSL2</h2><p>Use the Linux source route inside WSL2 with a matching architecture. WSL2 itself and native Windows remain unverified; native file-isolation tools are disabled.</p><button disabled>Release not published</button><small>Do not interpret source portability as verified native protection.</small></article></div><h2>Verify before you install.</h2><p>Download an artifact and its checksum manifest from the same official release. Inspect the release identity and any available provenance attestations. A checksum detects file changes; it does not establish publisher identity.</p><pre><code># macOS — verify the downloaded checksum file
shasum -a 256 -c sentinel-ai-0.3.0-rc.1-darwin-arm64.tar.gz.sha256

# Linux / WSL2 — from the release download directory
sha256sum -c sentinel-ai-0.3.0-rc.1-linux-aarch64.tar.gz.sha256</code></pre><p>Never disable Gatekeeper, Defender, your firewall or system integrity controls. Never pipe an unverified download into a shell.</p><a class="button secondary" href="/docs.html#install">Installation and upgrade guide ↗</a></section>'''
docs='''<section class="page-intro"><p class="eyebrow">DOCUMENTATION</p><h1>A clear boundary.<br>An explicit integration.</h1><p class="lede">Start locally, verify the enforcement path, then opt into cloud visibility.</p></section><div class="docs-layout"><aside aria-label="Documentation sections">'''+''.join(f'<a href="#{a}">{b}</a>' for a,b in [('install','Installation'),('start','Local runtime'),('integrate','Agent integration'),('operations','Supported tools'),('link','Link a device'),('privacy','Privacy'),('limitations','Security limits'),('trouble','Troubleshooting'),('remove','Uninstall'),('disclosure','Disclosure')])+'''</aside><div class="prose"><section id="install"><h2>Installation</h2><p>Use a platform-matched official GitHub release once published. Verify the checksum before extracting. Python 3.12+ is required; source builds additionally require the Rust toolchain specified in the repository. Native Windows filesystem isolation is unavailable; prefer WSL2.</p><p>The source repository contains the complete installer, upgrade and release verification instructions. No repository URL is configured here yet; the maintainer must set it before publication.</p></section><section id="start"><h2>Start the local runtime</h2><p>From your installed source directory, create a virtual environment, install the project using the repository’s instructions, and initialize a local administrator. Choose your own password; there is no default credential.</p><pre><code>python3.12 -m venv .venv
cargo build --locked
.venv/bin/python -m control_plane.server --init
.venv/bin/python -m control_plane.server --port 8787</code></pre><p>Open <code>http://127.0.0.1:8787</code> on the same machine. Keep this administrative interface on loopback. The online dashboard is separate and cannot grant local approvals.</p></section><section id="integrate"><h2>Connect a supported agent</h2><p>The Python SDK separates trusted task setup from untrusted tool proposals. Define exact permissions in a signed task contract, initialize the trusted runtime, and send each typed request through the gateway. Inspect its decision, execution flag and audit correlation identifier. A gateway error stops execution; it must never trigger a direct tool fallback.</p><p>See the repository’s SDK documentation and independent example agent. Ollama is optional. The supplied local model adapter accepts only loopback endpoints and validates one strict structured action per turn.</p><pre><code>.venv/bin/python -m agent_harness.live \
  --endpoint http://127.0.0.1:11434/v1/chat/completions \
  --model qwen2.5:3b --timeout 60 --max-steps 12</code></pre></section><section id="operations"><h2>Supported operations</h2><table><thead><tr><th>Operation family</th><th>Boundary</th></tr></thead><tbody><tr><td>read_file / write_file</td><td>Disposable simulated repository; exact contract resources.</td></tr><tr><td>api_get / api_post</td><td>Simulated services; no arbitrary external requests.</td></tr><tr><td>isolated_read / isolated_write</td><td>Unix pinned descriptors for reviewed fixture files. Unsupported native Windows capability is disabled.</td></tr><tr><td>wasm_run</td><td>Fixed reviewed checksum module, no WASI imports, bounded fuel and memory.</td></tr></tbody></table><p>There is no arbitrary shell, native program or general host filesystem interface.</p></section><section id="link"><h2>Link a device</h2><ol><li>Sign in to the cloud dashboard using the configured GitHub authentication provider.</li><li>Create a short-lived enrollment code in Devices. Treat the code as a secret.</li><li>Enter the code in the local synchronization client following the repository’s cloud-sync instructions.</li><li>Explicitly enable synchronization locally and in your cloud account. Linking alone does not authorize local tool actions.</li></ol><p>Enrollment codes are single-use. Revoke a device from the dashboard if its credential may be compromised. Connections originate from your computer; do not open inbound public ports.</p></section><section id="privacy"><h2>Local-first privacy</h2><p>Synchronization is off by default. Uploaded event records are restricted to opaque identifiers, timestamps, operation categories, decisions, execution flags, safe reason codes. Prompts, conversations, tool outputs, resource names, private paths, credentials and signing keys must remain local.</p><p>The cloud retains account identity, device metadata and selected telemetry. Events expire under the configured retention policy. You can delete events, revoke devices or delete your account from Settings. A compromised device can fabricate telemetry; cloud records are self-reported observations.</p></section><section id="limitations"><h2>Security limitations</h2><p>Sentinel protects only supported operations routed through its gateway. It cannot protect arbitrary ChatGPT, Claude, Codex or desktop activity automatically. Code executing outside the enforced tool interface is outside this boundary.</p><p>Descriptor pinning prevents path redirection for supported Unix fixture handles, not all same-user tampering. Wasm restrictions apply to the reviewed tool and do not establish an arbitrary native-code sandbox. Provenance controls are experimental. No complete prompt-injection immunity, formal audit or independent certification is claimed.</p></section><section id="trouble"><h2>Troubleshooting</h2><p><b>Cloud unavailable:</b> local authorization remains independent. Keep synchronization disabled or allow its bounded retry path; never bypass local policy.</p><p><b>Model errors:</b> confirm Ollama is serving the configured loopback endpoint and supports the strict JSON schema. Invalid output stops safely. Increase the bounded request timeout for slow inference.</p><p><b>Denied request:</b> inspect the safe reason code and local audit identifier. A denial is a policy outcome, not automatically an attack.</p><p><b>Login unavailable:</b> the operator must configure GitHub OAuth and the exact public origin. No production fallback account is provided.</p></section><section id="remove"><h2>Uninstall and upgrade</h2><p>Disable synchronization, revoke the device credential, stop the local runtime, and remove the installation environment. Use the synchronization client’s cleanup procedure to remove its credential from the operating-system store. Keep or securely remove local audit data according to your needs. Cloud data must be deleted separately from Settings.</p><p>Before upgrading, verify the new release, preserve your private state securely and review migration notes. Do not include private state in a support archive or public issue.</p></section><section id="disclosure"><h2>Vulnerability reporting</h2><p>Follow SECURITY.md in the official source repository. The maintainer must configure a private reporting channel before public release. Do not post credentials, private audit records or an unpatched exploit to a public issue. This candidate does not yet advertise a configured security contact.</p></section></div></div>'''
research='''<section class="page-intro"><p class="eyebrow">RESEARCH & EVIDENCE</p><h1>Measure the boundary.<br>State the limits.</h1><p class="lede">The working hypothesis: independent task-scoped enforcement can reduce unauthorized tool execution while preserving legitimate work on controlled workloads.</p></section><section><div class="section-head"><h2>Deterministic synthetic benchmark</h2><span class="tag">EXISTING LOCAL ARTIFACT</span></div><p>Seed 1729. Twenty repetitions of the same fixture; six unauthorized proposals per task. Completion requires the final summary to remain correct. These are repeated deterministic scenarios, not independent real-world attack samples.</p><div class="table-scroll"><table><thead><tr><th>Research arm</th><th>Unauthorized execution</th><th>Tasks completed</th><th>False denials</th></tr></thead><tbody><tr><td>Unrestricted simulation</td><td>120 / 120</td><td>0 / 20</td><td>0 / 140</td></tr><tr><td>Basic tool restrictions</td><td>60 / 120</td><td>0 / 20</td><td>0 / 140</td></tr><tr><td>Static policy comparator</td><td>20 / 120</td><td>0 / 20</td><td>0 / 140</td></tr><tr class="highlight"><td>Sentinel research runtime</td><td>0 / 120</td><td>20 / 20</td><td>0 / 140</td></tr></tbody></table></div><p class="caption">Source: benchmarks/phase2-results.json, macOS ARM64, Python 3.12.14. The comparator arms execute in memory; runtime latency is not an equivalent overhead comparison.</p><a href="/research-data.json">Read the original benchmark artifact ↗</a></section><section class="split-band"><div><p class="eyebrow">REAL LOCAL MODEL</p><h2>Qwen2.5:3b<br>through Ollama.</h2></div><div><p>Existing local runs used Ollama 0.40.3 and strict structured proposals. The sequenced clean run produced six allowed gateway actions; the sequenced injected run produced ten allowed actions and one denied unauthorized API request. Both wrote and read back authorized output with matching audit evidence.</p><p>Earlier runs stopped safely on invalid proposals or the step bound. Model-declared completion does not independently establish summary quality. These few smoke tests are not a prompt-injection robustness benchmark.</p><p class="caption">Source: docs/local-llm-integration.md and reports/qwen-live-*-sequenced.json, 2026-10-13. No independent replication or certification is claimed.</p></div></section><section><h2>Built on established methods.</h2><p>Capability security, sandboxing and authorization are established approaches. Sentinel’s potential contribution is a measurable combination of task authority, an independent gateway and constrained execution for agent workflows.</p><div class="three"><article><h3>AgentDojo</h3><p>A benchmark and environment for agent utility and prompt-injection robustness. Sentinel’s fixture results are not AgentDojo scores.</p><a href="https://github.com/ethz-spylab/agentdojo" rel="noreferrer">Read the project ↗</a></article><article><h3>CaMeL</h3><p>Separates control and data flow to contain prompt-injection effects. Sentinel’s sticky task taint is a narrower experimental mechanism.</p><a href="https://arxiv.org/abs/2503.18813" rel="noreferrer">Read the paper ↗</a></article><article><h3>Cedar & Wasmtime</h3><p>Existing policy and execution foundations. Their guarantees depend on correct integration and explicitly scoped host interfaces.</p><a href="https://docs.cedarpolicy.com/" rel="noreferrer">Cedar documentation ↗</a></article></div></section>'''
for file,title,body in [('index.html','Sentinel AI',home),('features.html','Features',features),('downloads.html','Downloads',downloads),('docs.html','Documentation',docs),('research.html','Research',research)]:
    (ROOT/file).write_text(page(title,body))
